(function(root){'use strict';
function eligible(recipe,data){return (data?.journals?Object.entries(data.journals):[]).filter(([id,j])=>j.validItems?.includes(recipe.id.split('@')[0])).map(([id,j])=>({id,...j}));}
function calculate(recipe,amount,cfg,data,fame,quote){if(!cfg.withJournals)return null;const books=eligible(recipe,data),j=books.find(j=>j.id===cfg.journalId)||books[0];if(!j)return {supported:false,missing:false,count:0,profit:0,reason:'У этого рецепта нет подходящего ремесленного журнала.'};const earned=Math.max(0,Number(fame?.[recipe.id])||0)*amount,count=Math.floor(earned/j.maxFame),empty=j.id+'_EMPTY',full=j.id+'_FULL',emptyQuote=cfg.journalEmptyPrice!==null&&cfg.journalEmptyPrice!==undefined&&cfg.journalEmptyPrice!==''?{price:Math.max(0,Number(cfg.journalEmptyPrice)||0),manual:true}:quote(empty,{purpose:'journal-buy',city:cfg.journalCity}),fullQuote=cfg.journalFullPrice!==null&&cfg.journalFullPrice!==undefined&&cfg.journalFullPrice!==''?{price:Math.max(0,Number(cfg.journalFullPrice)||0),manual:true}:quote(full,{purpose:'journal-sale',city:cfg.journalCity}),tax=Math.max(0,Number(cfg.tax)||0),setup=cfg.saleMode==='sell'?Math.max(0,Number(cfg.setup)||0):0,keep=cfg.saleMode==='discord'?1:1-(tax+setup)/100,discount=cfg.saleMode==='discord'?1-Math.max(0,Number(cfg.discount)||0)/100:1,emptyCost=count*emptyQuote.price,gross=count*fullQuote.price*discount,fees=gross*(1-keep);return {supported:true,id:j.id,empty,full,earned,maxFame:j.maxFame,count,remainder:earned-count*j.maxFame,emptyPrice:emptyQuote.price,fullPrice:fullQuote.price,emptyCost,gross,tax:cfg.saleMode==='discord'?0:gross*tax/100,setup:cfg.saleMode==='discord'?0:gross*setup/100,fees,profit:gross-fees-emptyCost,missing:count>0&&(!(emptyQuote.price>0)||!(fullQuote.price>0)||keep<=0)};}
const api={eligible,calculate};root.CraftJournalMath=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
